"""Run ordered, isolated backup on/off forks through run-single-benchmark.sh.

Equal durability (forceSync=true) is the primary comparison. With forceSync=false,
enabled journaling also strengthens commit durability; that pair is descriptive.
This script never builds or changes production classes and never drops failed runs.
"""

import argparse
import csv
import importlib.util
import json
import math
import os
from pathlib import Path
import platform
import shutil
import signal
import statistics
import subprocess
import time
import zipfile


REPO = Path(__file__).resolve().parents[1]
HELPER = Path(__file__).with_name("prepare-lmdb-backup-throughput-benchmark.py")
SPEC = importlib.util.spec_from_file_location("backup_harness", HELPER)
HARNESS = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(HARNESS)
MAIN = HARNESS.MAIN


def write_json(path, value):
    temporary = path.with_name(path.name + ".tmp")
    temporary.write_text(json.dumps(value, indent=2) + "\n")
    os.replace(temporary, path)


def read_optional(path):
    try:
        return Path(path).read_text()
    except OSError:
        return None


def environment_snapshot(storage):
    stat = os.statvfs(storage)
    result = {
        "time_epoch_seconds": time.time(),
        "storage": {"path": str(storage), "free_bytes": stat.f_bfree * stat.f_frsize,
                    "available_bytes": stat.f_bavail * stat.f_frsize},
        "affinity": sorted(os.sched_getaffinity(0)) if hasattr(os, "sched_getaffinity") else None,
        "proc": {}, "cgroup": {},
    }
    for name in ("meminfo", "vmstat", "stat", "loadavg", "pressure/cpu", "pressure/io", "pressure/memory"):
        result["proc"][name] = read_optional("/proc/" + name)
    for name in ("cpu.max", "cpu.stat", "memory.max", "memory.current", "memory.events", "memory.stat"):
        result["cgroup"][name] = read_optional("/sys/fs/cgroup/" + name)
    result["cgroup"]["available"] = any(value is not None for value in result["cgroup"].values())
    if not result["cgroup"]["available"]:
        result["cgroup"]["limitation"] = "No readable cgroup filesystem; counters are unavailable, not zero."
    return result


def find_benchmark_jvm(launcher_pid):
    """Inspect only this launcher's descendants, never unrelated host processes."""
    pending = [launcher_pid]
    seen = set()
    while pending:
        pid = pending.pop()
        if pid in seen:
            continue
        seen.add(pid)
        try:
            arguments = Path(f"/proc/{pid}/cmdline").read_bytes().split(b"\0")
            if arguments and arguments[0].rsplit(b"/", 1)[-1] in (b"java", b"java.exe") \
                    and MAIN.encode() in arguments:
                return pid
            children = read_optional(f"/proc/{pid}/task/{pid}/children")
            if children is not None:
                pending.extend(map(int, children.split()))
            else:
                # Some sandbox kernels omit the children file. Read parent IDs only;
                # command lines remain restricted to the launcher's descendants.
                for candidate in Path("/proc").iterdir():
                    if not candidate.name.isdigit():
                        continue
                    status = read_optional(candidate / "status")
                    if status is not None and any(line.split() == ["PPid:", str(pid)]
                                                   for line in status.splitlines()):
                        pending.append(int(candidate.name))
        except OSError:
            continue
    return None


def jvm_io_snapshot(pid):
    if pid is None:
        return {"available": False, "reason": "JVM descendant not discovered yet"}
    raw = read_optional(f"/proc/{pid}/io")
    counters = None if raw is None else {key.rstrip(":"): int(value)
                                        for key, value in (line.split() for line in raw.splitlines())}
    threads = {}
    task_directory = Path(f"/proc/{pid}/task")
    try:
        for task in task_directory.iterdir():
            name = read_optional(task / "comm")
            if name is not None:
                threads[task.name] = name.strip()
    except OSError:
        pass
    return {"available": raw is not None, "pid": pid, "counters": counters, "native_thread_names": threads,
            "scope": "whole JVM process, including publisher and cleanup threads"}


def writer_identity_from_lines(lines):
    header = None
    identity = None
    for line in lines:
        if not line.startswith("WRITER_NATIVE_THREAD,"):
            continue
        row = next(csv.reader([line]))
        if row[1:2] == ["label"]:
            header = row[1:]
        elif header is not None:
            identity = {key: scalar(value) for key, value in zip(header, row[1:], strict=True)}
    return identity


def thread_io_snapshot(pid, names, writer_identity):
    """Read only this verified JVM descendant's native tasks; retain raw identities and unavailable entries."""
    started = time.perf_counter_ns()
    result = {"available": False, "pid": pid, "writer_identity": writer_identity, "threads": {},
              "clock_ticks_per_second": os.sysconf("SC_CLK_TCK"),
              "scope": "Individual native threads; publisher/cleanup roles inferred from comm, writer mapped by JVM."}
    if pid is None:
        result["reason"] = "JVM descendant not discovered yet"
        return result
    writer_tid = None
    if writer_identity and writer_identity.get("available"):
        if writer_identity["process_id"] != pid or writer_identity["virtual"]:
            raise RuntimeError("Native writer identity does not match the owned platform-thread JVM")
        writer_tid = writer_identity["native_thread_id"]
    for tid, comm in names.items():
        task = Path(f"/proc/{pid}/task/{tid}")
        role = ("writer" if int(tid) == writer_tid else
                "process_leader" if int(tid) == pid else
                "publisher" if comm.startswith("LmdbBackupPubli") else
                "cleanup" if comm.startswith("LmdbValueCleanu") else "other")
        entry = {"native_tid": int(tid), "comm": comm, "role": role,
                 "role_source": "reported_proc_thread_self" if role == "writer" else
                                "pid" if role == "process_leader" else "comm_prefix",
                 "available": False}
        raw_io, raw_stat = read_optional(task / "io"), read_optional(task / "stat")
        if raw_io is None or raw_stat is None:
            entry["reason"] = "Native thread exited or io/stat could not be read"
        else:
            try:
                counters = {key.strip(): int(value) for key, value in
                            (line.split(":", 1) for line in raw_io.splitlines())}
                # /proc stat's comm field can contain spaces and parentheses.
                stat = raw_stat.rsplit(")", 1)[1].split()
                entry.update(available=True, counters=counters, user_cpu_ticks=int(stat[11]),
                             system_cpu_ticks=int(stat[12]), start_time_ticks=int(stat[19]))
                result["available"] = True
            except (ValueError, IndexError) as error:
                entry["reason"] = "Malformed native counter record: " + str(error)
        result["threads"][tid] = entry
    result["writer_observed"] = writer_tid is not None and str(writer_tid) in result["threads"] \
        and result["threads"][str(writer_tid)]["available"]
    result["observation_duration_nanos"] = time.perf_counter_ns() - started
    return result


def native_file_snapshot(stores):
    """Stat only known native files; never scan a per-transaction legacy archive."""
    result = {}
    for store in stores.iterdir():
        paths = [store / "values/data.mdb", store / "triples/data.mdb"]
        paths.extend(store.glob("backup/txlog/journal/*/data.mdb"))
        for path in paths:
            try:
                stat = path.stat()
                result[str(path.relative_to(stores))] = {
                    "logical_bytes": stat.st_size, "allocated_bytes": stat.st_blocks * 512}
            except OSError:
                # A warmup's owned temporary store can be removed between enumeration and stat.
                continue
    return result


def fingerprint(entries):
    result = {}
    for entry in entries:
        if entry.is_dir():
            result[str(entry)] = {path.relative_to(entry).as_posix(): HARNESS.sha256(path)
                                  for path in sorted(entry.rglob("*.class"))}
        else:
            result[str(entry)] = {"bytes": entry.stat().st_size, "sha256": HARNESS.sha256(entry)}
    return result


def prepare_run_jar(source, destination, entries):
    source_sha = HARNESS.sha256(HARNESS.SOURCE)
    with zipfile.ZipFile(source) as original:
        attributes = original.read("META-INF/MANIFEST.MF").decode().replace("\r\n ", "")
        if "Benchmark-Source-SHA256: " + source_sha not in attributes:
            raise RuntimeError("Harness source changed since compilation; recompile before measurement")
        with zipfile.ZipFile(destination, "w", zipfile.ZIP_DEFLATED) as target:
            target.writestr("META-INF/MANIFEST.MF", HARNESS.manifest_bytes(entries, source_sha))
            for name in original.namelist():
                if name.endswith(".class"):
                    target.writestr(name, original.read(name))


def scalar(value):
    if value in ("true", "false"):
        return value == "true"
    try:
        return int(value)
    except ValueError:
        try:
            return float(value)
        except ValueError:
            return value


def parse_log(path):
    result = {"intervals": [], "phases": [], "cpu": {}, "compilation_milliseconds": {}, "native_commits": [], "writer_native_thread": None}
    headers = {}
    for line in path.read_text(errors="replace").splitlines():
        row = next(csv.reader([line]))
        if not row:
            continue
        kind = row[0]
        if kind in ("RESULT", "INTERVAL", "NATIVE_COMMIT", "WRITER_NATIVE_THREAD"):
            if row[1:2] == ["label"]:
                headers[kind] = row[1:]
            elif kind in headers:
                parsed = {key: scalar(value) for key, value in zip(headers[kind], row[1:], strict=True)}
                if kind == "RESULT":
                    result["measurement"] = parsed
                elif kind == "INTERVAL":
                    result["intervals"].append(parsed)
                elif kind == "NATIVE_COMMIT":
                    result["native_commits"].append(parsed)
                else:
                    result["writer_native_thread"] = parsed
        elif kind == "PHASE":
            result["phases"].append({"phase": row[2], "started_epoch_millis": int(row[3]),
                                     "finished_epoch_millis": int(row[4]), "transactions": int(row[5])})
        elif kind == "CPU":
            result["cpu"][row[2]] = {key: float(value) if float(value) >= 0 else None
                                    for key, value in zip(("main_user_seconds", "main_cpu_seconds",
                                                           "process_cpu_seconds"), row[3:], strict=True)}
        elif kind == "COMPILATION":
            elapsed = int(row[3])
            result["compilation_milliseconds"][row[2]] = elapsed if elapsed >= 0 else None
        elif kind == "VALIDATION":
            result["validation"] = {key: scalar(value) for key, value in
                                    (item.split("=", 1) for item in row[2:])}
        elif kind == "CONFIG":
            result["config"] = dict(item.split("=", 1) for item in row[1:])
    if "measurement" not in result or "validation" not in result:
        raise RuntimeError("Run did not emit a complete, validated RESULT")
    measurement = result["measurement"]
    if measurement["final_backlog"] != 0 or not result["validation"].get("live_size"):
        raise RuntimeError("Run did not satisfy final drain and live-size checks")
    if measurement["backup"] and any(result["validation"].get(key) is not True
                                      for key in ("transaction_count", "acknowledgement", "head_identity")):
        raise RuntimeError("Enabled run did not satisfy publication checks")
    if result["config"].get("native_thread_report") == "true":
        identity = result["writer_native_thread"]
        if identity is None:
            raise RuntimeError("Requested native thread report was not emitted")
        if identity["available"] and (identity["virtual"] or identity["native_thread_id"] <= 0
                                      or identity["process_id"] <= 0):
            raise RuntimeError("Invalid reported native writer identity")
    if result["config"].get("native_commit_timing") == "true":
        rows = result["native_commits"]
        expected = {(environment, scope) for environment in ("values", "triples")
                    for scope in ("main", "background")}
        if len(rows) != 4 or {(row["environment"], row["thread_scope"]) for row in rows} != expected:
            raise RuntimeError("Native commit diagnostic did not emit all four environment/thread counters")
        if any(row["phase"] != "measurement" or row["failed_commits"] != 0
               or row["commits"] < 0 or row["nanos"] < row["maximum_nanos"]
               for row in rows):
            raise RuntimeError("Native commit diagnostic reported invalid or failed commits")
        if not any(row["environment"] == "triples" and row["thread_scope"] == "main"
                   and row["commits"] > 0 for row in rows):
            raise RuntimeError("Native commit diagnostic did not hit the main triples commit seam")
    cpu = result["cpu"]["measurement"]
    cpu["main_system_seconds"] = (cpu["main_cpu_seconds"] - cpu["main_user_seconds"]
                                  if cpu["main_cpu_seconds"] is not None and cpu["main_user_seconds"] is not None
                                  else None)
    cpu["per_transaction_microseconds"] = {
        name: value * 1e6 / measurement["transactions"] if value is not None else None
        for name, value in cpu.items() if name.endswith("seconds")
    }
    return result


def run_fork(args, entries, signature, size, force_sync, backup, pair):
    label = f"{args.label}-n{size}-sync{str(force_sync).lower()}-{'on' if backup else 'off'}-p{pair}"
    directory = args.output / label
    directory.mkdir(parents=True, exist_ok=False)
    target = directory / "target"
    target.mkdir()
    jar = target / "backup-throughput-benchmark.jar"
    prepare_run_jar(args.harness_jar, jar, entries)
    stores = directory / "stores"
    stores.mkdir()
    logging_config = directory / "logback-benchmark.xml"
    logging_config.write_bytes((REPO / "core/sail/lmdb/src/test/resources/logback-test.xml").read_bytes())
    launcher = REPO / "scripts/run-single-benchmark.sh"
    command = ["bash", str(launcher), "--module", os.path.relpath(directory, REPO), "--no-build",
               "--main-class", MAIN]
    extra_jvm_args = [value.replace("{run_dir}", str(directory)).replace("{label}", label)
                      for value in args.jvm_arg]
    jvm_args = ["-Xms512m", "-Xmx1g", f"-XX:ActiveProcessorCount={len(args.cpus)}",
                "-Dlogback.configurationFile=" + str(logging_config)] + extra_jvm_args
    for value in jvm_args:
        command += ["--jvm-arg", value]
    main_args = {"label": label, "statements": size, "force-sync": str(force_sync).lower(),
                 "backup": str(backup).lower(), "async-cleanup": "true",
                 "fresh-values": str(args.fresh_values).lower(),
                 "warmup-seconds": args.warmup_seconds, "warmup-rounds": args.warmup_rounds,
                 "min-warmup-transactions": args.min_warmup_transactions,
                 "measurement-seconds": args.measurement_seconds,
                 "pre-feature-parent": str(args.pre_feature_parent).lower(), "directory": str(stores)}
    if args.publication_observer is not None:
        main_args["publication-observer"] = args.publication_observer
    if args.native_commit_timing:
        main_args["native-commit-timing"] = "true"
    if args.thread_io:
        main_args["report-native-thread"] = "true"
    for key, value in main_args.items():
        command += ["--main-arg", "--" + key, "--main-arg", str(value)]
    if args.strace:
        command = [args.strace, "-ff", "-ttt", "-T", "-yy", "-s", "0", "-e",
                   "trace=pwrite64,pwritev,pwritev2,writev,fdatasync,fsync", "-o", str(directory / "syscalls"),
                   "--", *command]
    environment = os.environ.copy()
    environment["JAVA_HOME"] = str(args.java.resolve().parent.parent)
    environment["PATH"] = str(args.java.resolve().parent) + os.pathsep + environment.get("PATH", "")
    metadata = {"label": label, "pair": pair, "command": command, "cwd": str(REPO),
                "java": str(args.java), "affinity": args.cpus, "jvm_args": jvm_args,
                "publication_observer_requested": args.publication_observer,
                "classpath": list(map(str, entries)), "harness_sha256": HARNESS.sha256(jar),
                "logging_configuration_sha256": HARNESS.sha256(logging_config),
                "source_sha256": HARNESS.sha256(HARNESS.SOURCE), "before": environment_snapshot(directory)}
    write_json(directory / "command.json", metadata)
    if fingerprint(entries) != signature:
        raise RuntimeError("Runtime classes changed before fork; use a new campaign after rebuilding")
    timeout = args.fork_timeout or (args.warmup_seconds * args.warmup_rounds
                                   + args.measurement_seconds + args.drain_timeout)
    log_path = directory / "console.log"
    print(json.dumps({"event": "started", "label": label, "log": str(log_path), "timeout_seconds": timeout}),
          flush=True)
    started = time.monotonic()
    printed = 0
    timed_out = False
    jvm_pid = None
    writer_identity = None
    with log_path.open("w") as log, (directory / "environment-samples.jsonl").open("w") as samples:
        process = subprocess.Popen(command, cwd=REPO, env=environment, stdout=log, stderr=subprocess.STDOUT,
                                   start_new_session=True, preexec_fn=lambda: os.sched_setaffinity(0, args.cpus))
        try:
            while process.poll() is None:
                if jvm_pid is None:
                    jvm_pid = find_benchmark_jvm(process.pid)
                if args.thread_io:
                    lines = log_path.read_text(errors="replace").splitlines()
                    writer_identity = writer_identity_from_lines(lines) or writer_identity
                snapshot = environment_snapshot(directory)
                snapshot["jvm_io"] = jvm_io_snapshot(jvm_pid)
                if args.thread_io:
                    snapshot["thread_io"] = thread_io_snapshot(
                        jvm_pid, snapshot["jvm_io"].get("native_thread_names", {}), writer_identity)
                snapshot["native_files"] = native_file_snapshot(stores)
                samples.write(json.dumps(snapshot) + "\n")
                samples.flush()
                if not args.thread_io:
                    lines = log_path.read_text(errors="replace").splitlines()
                for line in lines[printed:]:
                    if line.startswith(("PHASE,", "CPU,", "COMPILATION,", "NATIVE_COMMIT,", "WRITER_NATIVE_THREAD,", "RESULT,")) \
                            and not line.startswith("RESULT,label,"):
                        print(line, flush=True)
                printed = len(lines)
                if time.monotonic() - started > timeout:
                    timed_out = True
                    os.killpg(process.pid, signal.SIGTERM)
                    try:
                        process.wait(timeout=10)
                    except subprocess.TimeoutExpired:
                        os.killpg(process.pid, signal.SIGKILL)
                    break
                time.sleep(1)
        finally:
            if process.poll() is None:
                os.killpg(process.pid, signal.SIGKILL)
            process.wait()
    metadata.update({"returncode": process.returncode, "timed_out": timed_out,
                     "jvm_pid": jvm_pid, "io_sampling_interval_seconds": 1,
                     "elapsed_seconds": time.monotonic() - started, "after": environment_snapshot(directory),
                     "runtime_unchanged": fingerprint(entries) == signature})
    write_json(directory / "command.json", metadata)
    if process.returncode != 0 or timed_out or not metadata["runtime_unchanged"]:
        raise RuntimeError(f"Failed or invalidated fork retained at {directory}")
    parsed = parse_log(log_path)
    for feature in ("native_engine", "adjacency"):
        if parsed["config"].get(feature) != "true" or parsed["validation"].get(feature) is not True:
            raise RuntimeError("Benchmark did not enable and verify " + feature)
    if parsed["validation"].get("adjacency_ready") is not True:
        raise RuntimeError("Benchmark did not fully drain direct adjacency maintenance")
    if parsed["measurement"].get("fresh_values") is not args.fresh_values:
        raise RuntimeError("Benchmark workload did not match the requested fresh-values setting")
    observer = parsed["measurement"].get("publication_observer")
    if args.publication_observer is not None:
        expected_observer = args.publication_observer if backup else "disabled"
        if observer != expected_observer:
            raise RuntimeError("Publication observer did not match the explicit protocol selection")
    if observer is not None:
        if parsed["config"].get("publication_observer") != observer:
            raise RuntimeError("Publication observer metadata disagrees between CONFIG and RESULT")
        if backup and parsed["validation"].get("acknowledgement_checkpoint") is not True:
            raise RuntimeError("Enabled run did not verify its post-close acknowledgement checkpoint")
    metadata["publication_observer_effective"] = observer or "unreported"
    write_json(directory / "command.json", metadata)
    parsed.update({"label": label, "pair": pair, "directory": str(directory),
                   "affinity": args.cpus, "runtime_unchanged": True})
    write_json(directory / "result.json", parsed)
    print(json.dumps({"event": "completed", "label": label, "measurement": parsed["measurement"],
                      "cpu": parsed["cpu"]["measurement"]}), flush=True)
    return parsed


def summarize(results):
    paired = {}
    for result in results:
        value = result["measurement"]
        key = (value["statements"], value["force_sync"], value.get("fresh_values", False), result["pair"])
        paired.setdefault(key, {})[value["backup"]] = value
    comparisons = []
    for (size, sync, fresh, pair), conditions in paired.items():
        if len(conditions) != 2:
            continue
        enabled, disabled = conditions[True], conditions[False]
        comparison = {"statements": size, "force_sync": sync, "fresh_values": fresh, "pair": pair,
                      "equal_durability": sync,
                      "interpretation": "journaling overhead" if sync else "journaling plus durable commits"}
        for metric in ("writer", "publication", "drained"):
            if metric + "_tps" not in enabled or metric + "_tps" not in disabled:
                continue
            # Use raw durations/counts; displayed TPS is deliberately rounded.
            tail = {"writer": None, "publication": "publication_complete_seconds",
                    "drained": "drain_seconds"}[metric]
            enabled_seconds = enabled["writer_seconds"] + (enabled[tail] if tail else 0)
            disabled_seconds = disabled["writer_seconds"] + (disabled[tail] if tail else 0)
            ratio = (enabled_seconds / enabled["transactions"]) / (disabled_seconds / disabled["transactions"])
            comparison[metric + "_added_time_percent"] = 100 * (ratio - 1)
        comparisons.append(comparison)
    aggregates = []
    for size, sync, fresh in sorted({(item["statements"], item["force_sync"], item["fresh_values"])
                                    for item in comparisons}):
        selected = [item for item in comparisons if item["statements"] == size and item["force_sync"] == sync
                    and item["fresh_values"] == fresh]
        aggregate = {"statements": size, "force_sync": sync, "fresh_values": fresh, "equal_durability": sync,
                     "pairs": len(selected)}
        for metric in ("writer", "publication", "drained"):
            values = [item[metric + "_added_time_percent"] for item in selected
                      if metric + "_added_time_percent" in item]
            if not values:
                continue
            aggregate[metric] = {"mean_added_time_percent": statistics.mean(values),
                                 "minimum": min(values), "maximum": max(values),
                                 "standard_deviation": statistics.stdev(values) if len(values) > 1 else None,
                                 "geometric_mean_added_time_percent":
                                     100 * (math.exp(statistics.mean(math.log1p(value / 100) for value in values)) - 1),
                                 "all_observed_pairs_below_five_percent": all(value < 5 for value in values)}
        aggregates.append(aggregate)
    return {"comparisons": comparisons, "aggregates": aggregates,
            "limitations": ["Each row describes this bounded workload and environment, not every RDF workload.",
                            "A single favorable fork or profiled diagnostic is not acceptance.",
                            "forceSync=false on/off differs in commit durability and is not isolated overhead."]}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--classpath-file", required=True, type=Path)
    parser.add_argument("--harness-jar", required=True, type=Path)
    parser.add_argument("--output", required=True, type=Path)
    parser.add_argument("--label", default="current")
    parser.add_argument("--java", type=Path, default=shutil.which("java"))
    parser.add_argument("--cpus", default="0,1,2,3")
    parser.add_argument("--statements", default="1,10,100")
    parser.add_argument("--force-sync", default="true,false")
    parser.add_argument("--conditions", choices=("on,off", "off,on", "on", "off"), default="off,on")
    parser.add_argument("--fresh-values", action="store_true",
                        help="Create new lexical literals on every insertion; exact prior values are removed, so live data stays bounded")
    parser.add_argument("--pairs", type=int, default=3)
    parser.add_argument("--warmup-seconds", type=int, default=20)
    parser.add_argument("--warmup-rounds", type=int, default=2)
    parser.add_argument("--min-warmup-transactions", type=int, default=0,
                        help="Minimum completed transactions in each warmup round, in addition to its duration")
    parser.add_argument("--measurement-seconds", type=int, default=20)
    parser.add_argument("--drain-timeout", type=int, default=180)
    parser.add_argument("--fork-timeout", type=int,
                        help="Explicit total fork timeout when minimum warmup work may extend the time budget")
    parser.add_argument("--pre-feature-parent", action="store_true",
                        help="Run an exact pre-feature artifact with --conditions off; skip absent backup setup APIs")
    parser.add_argument("--native-commit-timing", action="store_true",
                        help="Diagnostic-only measured native commit seams by environment and main/background thread")
    parser.add_argument("--thread-io", action="store_true",
                        help="Opt-in native thread io/comm/stat snapshots with one pre-warmup writer TID report")
    parser.add_argument("--publication-observer", choices=("publisher", "file"),
                        help="Explicit running-store durable proof: optimized publisher tuple or original-main file; omitted for older harnesses")
    parser.add_argument("--harness-source", type=Path,
                        help="Explicit frozen source snapshot for validating an older harness JAR")
    parser.add_argument("--jvm-arg", action="append", default=[],
                        help="Extra diagnostic JVM flag; {run_dir} and {label} expand uniquely for each fork")
    parser.add_argument("--strace", metavar="EXECUTABLE",
                        help="Diagnostic syscall trace executable; traced forks are never acceptance samples")
    args = parser.parse_args()
    if args.harness_source is not None:
        HARNESS.SOURCE = args.harness_source.resolve()
    args.output = args.output.resolve()
    args.harness_jar = args.harness_jar.resolve()
    args.cpus = [int(cpu) for cpu in args.cpus.split(",")]
    sizes = [int(size) for size in args.statements.split(",")]
    sync_values = args.force_sync.split(",")
    if not args.java or not args.java.exists() or not args.harness_jar.exists():
        parser.error("Provide an existing Java executable and compiled harness JAR")
    if any(value not in ("true", "false") for value in sync_values):
        parser.error("--force-sync must contain true and/or false")
    if args.pairs < 1 or any(size < 1 for size in sizes) or not args.cpus:
        parser.error("At least one pair, statement and CPU are required")
    if args.min_warmup_transactions < 0 or args.warmup_seconds < 0 or args.warmup_rounds < 1 \
            or args.measurement_seconds < 1 or args.drain_timeout < 1 \
            or (args.fork_timeout is not None and args.fork_timeout < 1):
        parser.error("Warmup counts/duration must be nonnegative and other durations/rounds positive")
    if args.pre_feature_parent and args.conditions != "off":
        parser.error("--pre-feature-parent requires --conditions off")
    if args.pre_feature_parent and args.native_commit_timing:
        parser.error("Native commit timing is unavailable for the exact pre-feature parent")
    if not set(args.cpus).issubset(os.sched_getaffinity(0)):
        parser.error("Requested CPUs are outside this process's allowed affinity")
    entries = HARNESS.classpath_entries(args.classpath_file)
    args.output.mkdir(parents=True, exist_ok=True)
    campaign_path = args.output / "campaign.json"
    if campaign_path.exists():
        parser.error("Output already contains a campaign; use a fresh directory to preserve every fork")
    signature = fingerprint(entries)
    write_json(args.output / "runtime-fingerprints.json", signature)
    release = read_optional(args.java.resolve().parent.parent / "release")
    campaign = {"arguments": {key: str(value) if isinstance(value, Path) else value
                              for key, value in vars(args).items()},
                "started_epoch_seconds": time.time(), "jdk_release": release,
                "host": {"kernel": platform.uname()._asdict(), "cpuinfo": read_optional("/proc/cpuinfo"),
                         "mountinfo": read_optional("/proc/self/mountinfo")},
                "git_commit": subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=REPO, text=True).strip(),
                "source_sha256": HARNESS.sha256(HARNESS.SOURCE),
                "harness_sha256": HARNESS.sha256(args.harness_jar), "completed_runs": []}
    write_json(campaign_path, campaign)
    results = []
    try:
        for sync_value in sync_values:
            for size in sizes:
                for pair in range(1, args.pairs + 1):
                    conditions = args.conditions.split(",")
                    if pair % 2 == 0:
                        conditions.reverse()
                    for condition in conditions:
                        result = run_fork(args, entries, signature, size, sync_value == "true",
                                          condition == "on", pair)
                        results.append(result)
                        campaign["completed_runs"].append(result["label"])
                        write_json(campaign_path, campaign)
                        write_json(args.output / "summary.json", summarize(results))
    except BaseException as error:
        campaign["failure"] = str(error)
        raise
    finally:
        campaign["finished_epoch_seconds"] = time.time()
        write_json(campaign_path, campaign)
    print(json.dumps({"event": "campaign_complete", "summary": summarize(results)}), flush=True)


if __name__ == "__main__":
    main()
